// === Tab: mySketch ===
// let Risou
// https://risoume.github.io/

let x, y, w, h, pad;

let brown = "#f9a26c"; // flower let color greenbg = "#9bd7d1";
let shadow = "#2B3564";
let bg = "#E8ECFF";

let p1 = new PVector(-15, 30);
let p2 = new PVector(15, 30);

function setup() {
  createCanvas(600, 600);
  noLoop();
  init();
}

function init() {
  x = 120;
  y = 160;
  w = width-2*x;
  h = height-2*y;
  pad = 15;
}

function draw() {
  background(bg);
  strokeWeight(1);

  let off = 5;
  let diff = 60;
  let p = 40;

  noStroke();
  fill(greenbg);
  for (i = diff; i < h-2*pad-p; i += diff) {
    rect(0, y+pad+i, width, p);
  }

  translate(x, y);
  pushMatrix();
  translate(off, off);
  noStroke();
  frame(shadow);
  popMatrix();

  for (m = 50; m < w-30; m += 50) {
    stroke(0);
    noFill();
    arc(pad+m, h-pad, 20, random(30, 40), PI, 3*PI/2);
    arc(pad+m, h-pad, 20, random(40, 50), PI, 3*PI/2);
    arc(pad+m-20, h-pad, 20, random(40, 50), 3*PI/2, 2*PI);
    let tallest = random(60, 70);
    let sz2 = 8;
    if (random(1) < 0.5) {
      arc(pad+m-20, h-pad, 20, tallest, 3*PI/2, 2*PI);
      noStroke();
      fill(255);
      rect(pad+m-20-10+5, h-pad-tallest/2-5, sz2, sz2);
    } else {
      arc(pad+m, h-pad, 20, tallest, PI, 3*PI/2);
      noStroke();
      fill(255);
      rect(pad+m-10+5, h-pad-tallest/2-5, sz2, sz2);
    }
  }
  stroke(0);
  frame(bg);

  let rot = 35;
  let space = 50;

  stroke(0);
  fill(brown);
  pushMatrix();
  translate(pad+space+25, pad);
  rotate(radians(15));
  line(0, 0, 0, 150);
  translate(0, 150);
  for (i = 0; i < 360/rot; i++) {
    bezier(0, 0, p1.x+int(random(-5, 5)), p1.y+int(random(-5, 5)), p2.x+int(random(-5, 5)), p2.y+int(random(-5, 5)), 0, 0);
    rotate(radians(rot));
  }
  fill(255, 255, 0);
  ellipse(0, 0, 10, 10);
  popMatrix();

  for (j = 2*space+25; j < w-2*pad-10; j += space) {
    noFill();
    line(pad+j, pad, pad+j, pad+150);
    pushMatrix();
    translate(pad+j, pad+150);
    for (i = 0; i < 360/rot; i++) {
      bezier(0, 0, p1.x+int(random(-5, 5)), p1.y+int(random(-5, 5)), p2.x+int(random(-5, 5)), p2.y+int(random(-5, 5)), 0, 0);
      rotate(radians(rot));
    }
    fill(255, 255, 0);
    ellipse(0, 0, 10, 10);
    popMatrix();
  }
  noStroke();
}

function frame(c) {
  fill(c);
  beginShape();
  vertex(w, pad+100);
  vertex(w-pad, pad+100);
  vertex(w-pad, pad);
  vertex(pad, pad);
  vertex(pad, h-pad);
  vertex(w-pad, h-pad);
  vertex(w-pad, pad+165);
  vertex(w, pad+165);
  vertex(w, h);
  vertex(0, h);
  vertex(0, 0);
  vertex(w, 0);
  vertex(w, pad+100);
  endShape();
}

function mouseReleased() {
  init();
  redraw();
}

